// AWI: halaman model yang punya video sendiri (penanda awi-...video-start) tidak perlu tombol video YouTube bawaan tema. Dipasang Claude 14 Nov 2026.
add_action('template_redirect', function () {
	if (is_admin() || wp_doing_ajax() || is_feed() || (defined('REST_REQUEST') && REST_REQUEST)) return;
	if (!is_singular('model')) return;
	ob_start(function ($html) {
		if (!is_string($html) || !preg_match('#awi-[a-z0-9]+video-start#', $html)) return $html;
		return preg_replace('#<div class="model__leftvideo">(?:(?!<div\b).)*?</div>#s', '', $html, 1);
	});
}, 96);
